package com.riskguard.transaction;
import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
import com.riskguard.transaction.domain.*; import com.riskguard.transaction.service.JwtTokenService; import java.time.*; import java.util.UUID; import org.junit.jupiter.api.Test; import org.mockito.ArgumentCaptor; import org.springframework.security.oauth2.jwt.*;
class JwtTokenServiceTest { @Test void issuesShortLivedTokenWithSubjectEmailAndRole(){ JwtEncoder encoder=mock(JwtEncoder.class); Jwt jwt=mock(Jwt.class); when(jwt.getTokenValue()).thenReturn("signed-token"); when(encoder.encode(any())).thenReturn(jwt); UUID id=UUID.randomUUID(); Instant now=Instant.parse("2026-01-01T00:00:00Z"); String token=new JwtTokenService(encoder).issue(new UserAccount(id,"analyst@example.com","hash",Role.ANALYST,now),now,now.plusSeconds(900)); assertThat(token).isEqualTo("signed-token"); ArgumentCaptor<JwtEncoderParameters> captor=ArgumentCaptor.forClass(JwtEncoderParameters.class); verify(encoder).encode(captor.capture()); JwtClaimsSet claims=captor.getValue().getClaims(); assertThat(claims.getSubject()).isEqualTo(id.toString()); assertThat(claims.getClaimAsString("email")).isEqualTo("analyst@example.com"); assertThat(claims.getClaim("roles").toString()).contains("ROLE_ANALYST"); assertThat(claims.getExpiresAt()).isEqualTo(now.plusSeconds(900)); } }
